WITH dossier_seed(payload) AS (
  VALUES ('[{"slug":"magic-eden-marketplace","name":"Magic Eden Marketplace","chain":"solana","category":"nft-marketplace-platform","status":"declining","profile":{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"direct_current","status_as_of":"2026-07-28","last_verified_at":"2026-07-29","next_review_at":"2026-08-05","stale":false},"launched":"Magic Eden dates its inception to September 2021 and began as a Solana NFT marketplace. This dossier evaluates the marketplace platform, not the separate ME token as an investment.","supply":"Not applicable: Magic Eden is a marketplace, not a fixed-supply collection. Marketplace inventory, wallets and token holders are different populations and are not reported here as supply.","mint_price":"Not applicable platform-wide. Collection creators and sellers set asset-specific economics; no defensible universal mint price or aggregate creator raise is available from the cited operator material.","community_history":"Magic Eden expanded from Solana into Bitcoin, Runes, EVM marketplaces, APIs and a wallet, then announced a 2026 retrenchment. EVM and Bitcoin marketplace surfaces ended March 9, Bitcoin and Runes APIs ended March 27, and the wallet was scheduled to shut May 1; Solana marketplace and Packs remained supported.","founder_engagement":"The cited support record documents an operator-led product reset and says the $ME token remains tied to an evolving Dicey roadmap. It does not establish founder retention, staffing, revenue, or whether discontinued products were sold or simply closed.","benefits":"The remaining NFT product offers Solana marketplace activity and Packs. ME staking remains documented as a lock-and-reward mechanism, but staking availability does not establish marketplace demand, token value capture, or financial sustainability.","business":"The strategic choice was broad multi-chain expansion followed by concentration on Solana and Packs while ending Bitcoin, Runes, EVM and wallet surfaces. That reduces product breadth and operating surface area, but current revenue, costs, retained users and profitability are undisclosed.","analysis":"Declining is a scoped marketplace-platform classification: multiple previously promoted product and chain surfaces were explicitly discontinued while a narrower Solana marketplace remained live. The evidence does not establish insolvency, total company failure, current market share, organic volume, liquidity quality, revenue or profitability.","team":{"operator":"Magic Eden","founder_and_staffing_boundary":"Current founder roles and staffing levels were not established by the cited product notices.","source_ids":["magic-eden-service-changes"]},"chronology":[{"date":"2021","event":"Magic Eden launched as a Solana NFT marketplace.","source_ids":["magic-eden-inception"]},{"date":"2026-03-09","event":"Magic Eden ended its EVM and Bitcoin marketplace surfaces.","source_ids":["magic-eden-service-changes"]},{"date":"2026-03-27","event":"Magic Eden ended Bitcoin and Runes API access.","source_ids":["magic-eden-service-changes","magic-eden-api-changes"]},{"date":"2026-05-01","event":"The operator scheduled the Magic Eden Wallet for shutdown while retaining Solana marketplace and Packs.","source_ids":["magic-eden-service-changes"]}],"market_holder_boundaries":{"market":"No independently verified current NFT volume, market share, active-trader, bid-depth, fee-revenue or profitability series was established.","holders":"Not a collection: marketplace users, wallets, collection holders and ME token holders are distinct populations.","available_evidence":"The operator''s current chain-support and shutdown notices establish product scope, not market quality.","source_ids":["magic-eden-service-changes","magic-eden-supported-chains"]},"products_and_value_capture":{"products":["Solana NFT marketplace","Packs","ME token staking","Dicey roadmap referenced by the operator"],"capture":"Marketplace and token-related value capture cannot be quantified from the cited sources; staking rewards are a mechanism, not proof of sustainable fee demand.","source_ids":["magic-eden-service-changes","magic-eden-staking"]},"token_model":{"token":"ME","observed_role":"Lock-based staking and rewards are documented; the service-change notice says the token remains tied to an evolving Dicey roadmap.","boundary":"No claim is made about token price, circulating supply, revenue rights, sustainable yield or marketplace value capture.","source_ids":["magic-eden-staking","magic-eden-service-changes"]},"chain_dependence":{"current_scope":"The cited current support page lists Solana for NFT transactions after Bitcoin and EVM marketplace discontinuations.","implication":"Concentration reduces multichain complexity but increases dependence on Solana collector demand and ecosystem distribution.","source_ids":["magic-eden-supported-chains","magic-eden-service-changes"]},"why":{"finding":"The platform is declining in scope because a broad expansion strategy was reversed: Bitcoin, Runes, EVM and wallet surfaces were closed while the business concentrated on Solana, Packs and a changing ME/Dicey roadmap. The causal evidence establishes retrenchment, not the undisclosed financial reason for it.","source_ids":["magic-eden-service-changes","magic-eden-api-changes","magic-eden-supported-chains"]},"strategic_choices":[{"choice":"Expand beyond the original Solana marketplace into Bitcoin, Runes, EVM products, APIs and a wallet.","consequence":"The operator accumulated a wide product and chain surface that it later discontinued in several areas.","source_ids":["magic-eden-service-changes","magic-eden-api-changes"]},{"choice":"End Bitcoin, Runes and EVM marketplace/API surfaces rather than maintain broad chain coverage.","consequence":"The marketplace became materially narrower and current NFT support concentrated on Solana.","source_ids":["magic-eden-service-changes","magic-eden-supported-chains"]},{"choice":"Retain Solana marketplace, Packs and the ME-linked Dicey direction while closing the wallet.","consequence":"The surviving thesis depends more heavily on a smaller set of products and on converting token/reward engagement into durable marketplace demand.","source_ids":["magic-eden-service-changes","magic-eden-staking"]}],"counterfactual":{"finding":"A narrower Solana-first expansion might have avoided some multichain and wallet operating complexity, but the cited sources do not disclose segment costs or prove that breadth caused the retrenchment. Conversely, keeping every surface open without demonstrated demand could have preserved breadth while increasing maintenance burden.","source_ids":["magic-eden-service-changes","magic-eden-api-changes","magic-eden-supported-chains"]},"risks":[{"risk":"Further product concentration or shutdown could weaken marketplace distribution.","source_ids":["magic-eden-service-changes"]},{"risk":"ME staking incentives may not translate into organic marketplace demand or sustainable value capture.","source_ids":["magic-eden-staking"]},{"risk":"Current dependence on Solana exposes the remaining marketplace to one chain''s collector activity and infrastructure.","source_ids":["magic-eden-inception"]}],"unknowns":["Current active traders, organic NFT volume, bid depth and Solana market share.","Segment revenue, fee take rate, rebates, operating costs, runway and profitability.","The financial versus strategic causes of each 2026 product shutdown.","ME token liabilities, sustainable reward funding and measurable marketplace value capture.","Current founder roles, headcount, customer-support outcomes and retained users after the reset."],"review":{"last_verified_at":"2026-07-29","next_review_at":"2026-08-05","triggers":["additional product shutdown","new chain support","Dicey or ME roadmap change","audited usage or financial disclosure"]},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"declining","summary":"Previously operated Bitcoin, Runes, EVM and wallet surfaces were discontinued while a narrower Solana marketplace remained supported.","confidence":"high","as_of":"2026-07-28","source_refs":["magic-eden-service-changes","magic-eden-supported-chains"]},"why":{"summary":"The directly evidenced cause of the declining classification is product-scope retrenchment after multichain expansion; the underlying financial cause remains undisclosed.","confidence":"high","source_refs":["magic-eden-service-changes","magic-eden-api-changes"]},"strategic_choices":[{"decision":"Expand into multiple chain marketplaces, APIs and a wallet.","consequence":"Created a broader surface that was later materially reduced.","confidence":"high","source_refs":["magic-eden-service-changes","magic-eden-api-changes"]},{"decision":"Concentrate the surviving NFT marketplace on Solana and Packs.","consequence":"Reduced breadth while increasing reliance on a smaller product and chain base.","confidence":"high","source_refs":["magic-eden-service-changes","magic-eden-supported-chains"]},{"decision":"Continue ME staking and an evolving Dicey-linked roadmap.","consequence":"Keeps a token/reward thesis alive without proving sustainable marketplace demand.","confidence":"medium","source_refs":["magic-eden-staking","magic-eden-service-changes"]}],"counterfactual":{"summary":"A Solana-first strategy may have reduced operating complexity, but no cited segment economics establish that expansion itself caused the closures.","confidence":"low","source_refs":["magic-eden-service-changes","magic-eden-supported-chains"]},"watch":[{"signal":"Any additional shutdown or restored chain support.","implication":"Would distinguish continued contraction from stabilization.","source_refs":["magic-eden-service-changes"]},{"signal":"Audited active-user, fee-revenue or ME value-capture disclosure.","implication":"Would test whether the narrower product set is economically durable.","source_refs":["magic-eden-staking"]}],"unknowns":["Why management closed each product.","Whether the remaining marketplace is profitable.","Whether ME rewards drive retained organic demand.","How many users migrated or churned after the reset."],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"Chaindump Research"}},"evidence":[{"field":"launch","value":"Launched in 2021 as a Solana NFT marketplace","as_of":"2021-12-31","basis":"operator","source_ids":["magic-eden-supported-chains"]},{"field":"supply_or_mint","value":"Not applicable to a marketplace platform; inventory and users are not collection supply","as_of":"2026-07-28","basis":"analyst","source_ids":["magic-eden-supported-chains"]},{"field":"mint_price","value":"Not applicable platform-wide; collection and seller economics vary","as_of":"2026-07-28","basis":"operator","source_ids":["magic-eden-supported-chains"]},{"field":"lifecycle_status","value":"declining — material product and chain retrenchment with Solana marketplace still live","as_of":"2026-07-28","basis":"analyst","source_ids":["magic-eden-service-changes","magic-eden-supported-chains"]},{"field":"community_history","value":"Expanded beyond Solana, then ended EVM, Bitcoin, Runes API and wallet surfaces in 2026","as_of":"2026-07-28","basis":"operator","source_ids":["magic-eden-service-changes","magic-eden-api-changes"]},{"field":"founder_engagement","value":"Operator documented the reset; current founder roles and staffing remain unverified","as_of":"2026-07-28","basis":"analyst","source_ids":["magic-eden-service-changes"]},{"field":"benefits","value":"Solana marketplace, Packs and ME staking remain documented; financial durability withheld","as_of":"2026-07-28","basis":"operator","source_ids":["magic-eden-service-changes","magic-eden-staking"]},{"field":"business","value":"Multichain expansion followed by Solana concentration; current revenue and profitability withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["magic-eden-service-changes","magic-eden-supported-chains"]},{"field":"analysis","value":"Scope decline is directly observed; insolvency, market share and profitability are not established","as_of":"2026-07-28","basis":"analyst","source_ids":["magic-eden-service-changes","magic-eden-supported-chains"]}]},"sources":[{"id":"magic-eden-inception","title":"Introducing Magic Eden Rewards","url":"https://community.magiceden.io/culture/rewards-manifesto","publisher":"Magic Eden","source_date":null,"source_date_kind":"unknown","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false},{"id":"magic-eden-service-changes","title":"Magic Eden Marketplace Updates & Service Changes","url":"https://help.magiceden.io/en/articles/13885504-magic-eden-marketplace-updates-service-changes","publisher":"Magic Eden","source_date":"2026-03-09","source_date_kind":"event","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-08-05","stale":false},{"id":"magic-eden-supported-chains","title":"Supported Currencies and Blockchains for NFT Transactions","url":"https://help.magiceden.io/en/articles/6483913-supported-currencies-and-blockchains-for-nft-transactions-on-magic-eden","publisher":"Magic Eden","source_date":"2026-07-28","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-08-05","stale":false},{"id":"magic-eden-api-changes","title":"Magic Eden API Infrastructure Changes","url":"https://help.magiceden.io/en/articles/13885533-magic-eden-api-infrastructure-changes","publisher":"Magic Eden","source_date":"2026-03-27","source_date_kind":"event","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false},{"id":"magic-eden-staking","title":"How to Stake ME","url":"https://help.magiceden.io/en/articles/10256546-how-to-stake-me","publisher":"Magic Eden","source_date":"2026-07-28","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-08-05","stale":false}]},{"slug":"gamma-ordinals-platform","name":"Gamma Ordinals","chain":"bitcoin-ordinals","category":"ordinals-marketplace-launchpad","status":"thriving","profile":{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"direct_current","status_as_of":"2026-07-28","last_verified_at":"2026-07-29","next_review_at":"2026-10-29","stale":false},"launched":"Gamma released its no-code Ordinals inscription tool on February 8, 2023. The current platform is operated by Nassau Machines Inc. and offers creator minting, drops, prints and a secondary marketplace on Bitcoin.","supply":"Not applicable: Gamma is a launchpad and marketplace, not one collection. Operator totals for items sold, creators and collectors are platform metrics, not fixed supply or independently audited users.","mint_price":"Not applicable platform-wide. Creators configure individual drops and inscriptions; no universal mint price or aggregate primary raise is established.","community_history":"Gamma extended its creator tooling into a no-code Bitcoin Ordinals launchpad and marketplace. Its live platform shows current drops, prints, creator pages and marketplace inventory, while creator terms updated in April 2026 define the operator''s role and moderation boundaries.","founder_engagement":"Nassau Machines Inc. is the identified legal operator. Current founder identities, staffing, treasury and financing were not established by the cited first-party pages.","benefits":"Creators can launch Ordinals collections through a no-code portal and collectors can mint, collect and trade through a Bitcoin-focused marketplace. Gamma can moderate its own pages but cannot prevent protocol-level contract use elsewhere.","business":"The product combines creator launch tooling, primary drops and a secondary marketplace. Gamma publishes cumulative platform metrics, but those issuer-reported totals do not establish current organic demand, fee revenue, creator retention or profitability.","analysis":"Thriving means the Bitcoin Ordinals creator and marketplace product was live, legally documented and showing active drops and inventory. It is an operational classification, not a claim that Gamma leads the market or that its reported totals are audited, current-period, wash-adjusted or profitable.","team":{"legal_operator":"Nassau Machines Inc.","founder_and_staffing_boundary":"Founder roles, headcount, financing and treasury are undisclosed in the cited first-party pages.","source_ids":["gamma-creator-terms"]},"chronology":[{"date":"2023","event":"Gamma developed Bitcoin Ordinals creator and marketplace tooling during the initial Ordinals cycle.","source_ids":["gamma-ordinals-launch"]},{"date":"2026-04-08","event":"Gamma updated its creator terms for mint pages and marketplace activity.","source_ids":["gamma-creator-terms"]},{"date":"2026-07-28","event":"Current drops, prints, creators, no-code launch tooling and marketplace inventory were visible.","source_ids":["gamma-ordinals-launch"]},{"date":"2026-07-28","event":"The operator displayed cumulative creator, collector and sales metrics; Chaindump treats them as unaudited issuer reports.","source_ids":["gamma-platform"]}],"market_holder_boundaries":{"market":"No independently verified current volume, fee revenue, wash-adjusted trades, bid depth, market share or profitability series.","holders":"Not a collection: creators, collectors, wallets, buyers and owners across many collections cannot be collapsed into one holder count.","available_evidence":"The live product and current legal terms establish operation and product scope; operator cumulative metrics are clearly bounded.","source_ids":["gamma-platform","gamma-creator-terms"]},"products_and_value_capture":{"products":["No-code Ordinals launchpad","primary drops","prints","secondary marketplace","creator pages"],"capture":"Potential launch and marketplace fees are not quantified in the cited pages; current revenue, costs and profitability are withheld.","source_ids":["gamma-platform","gamma-creator-terms"]},"token_model":{"token":"No platform token established by the cited sources","observed_role":"The product is described through creator tooling and marketplace services rather than token incentives.","boundary":"Absence from these cited pages is not proof that no future or affiliated token exists.","source_ids":["gamma-platform","gamma-creator-terms"]},"chain_dependence":{"current_scope":"This dossier covers Gamma''s Bitcoin Ordinals product.","implication":"The thesis depends on Bitcoin inscription demand, fees, indexer reliability and creator adoption rather than a general multichain NFT market.","source_ids":["gamma-platform"]},"why":{"finding":"Gamma remains operational because it serves both supply creation and secondary discovery in a specialized Ordinals workflow: no-code creator tooling, primary drops and a marketplace share the same Bitcoin-focused distribution surface. The evidence does not establish that vertical integration is profitable.","source_ids":["gamma-platform","gamma-creator-terms"]},"strategic_choices":[{"choice":"Build no-code Ordinals creation tools alongside marketplace discovery.","consequence":"Gamma can acquire creators at launch and retain their collections on the same discovery surface.","source_ids":["gamma-platform"]},{"choice":"Specialize the evaluated product on Bitcoin inscriptions rather than present it as a generic NFT marketplace.","consequence":"The positioning is differentiated but tightly exposed to Ordinals demand and Bitcoin infrastructure.","source_ids":["gamma-platform"]},{"choice":"Reserve moderation rights over Gamma pages while acknowledging protocol use can persist elsewhere.","consequence":"The operator can control its interface but cannot promise protocol-level removal or complete marketplace enforcement.","source_ids":["gamma-creator-terms"]}],"counterfactual":{"finding":"A marketplace without creator tooling would have less control over collection onboarding, while a launchpad without secondary discovery would lose downstream engagement. The combined model plausibly improves distribution, but no cited cohort data proves better retention or economics.","source_ids":["gamma-platform","gamma-creator-terms"]},"risks":[{"risk":"Bitcoin fee spikes or indexer failures can impair minting and marketplace experience.","source_ids":["gamma-platform"]},{"risk":"Issuer-reported cumulative totals can obscure current-period demand and repeat-user retention.","source_ids":["gamma-platform"]},{"risk":"Interface moderation cannot guarantee protocol-level removal or control of assets elsewhere.","source_ids":["gamma-creator-terms"]}],"unknowns":["Current active creators, collectors, repeat retention and cohort conversion.","Current organic volume, wash-adjusted trades, bid depth and market share.","Fee schedule economics, revenue, creator payouts, costs and profitability.","The share of cumulative operator metrics generated in the latest quarter.","Current founder roles, headcount, financing and treasury."],"review":{"last_verified_at":"2026-07-29","next_review_at":"2026-10-29","triggers":["creator terms change","launchpad or marketplace shutdown","new audited activity disclosure","material Bitcoin Ordinals protocol change"]},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"thriving","summary":"Gamma''s Bitcoin Ordinals launchpad, drops, prints and marketplace remained live with current creator terms.","confidence":"high","as_of":"2026-07-28","source_refs":["gamma-platform","gamma-creator-terms"]},"why":{"summary":"A vertically integrated creator-to-secondary-market workflow provides a coherent niche operating thesis, although financial success is unproven.","confidence":"medium","source_refs":["gamma-platform","gamma-creator-terms"]},"strategic_choices":[{"decision":"Pair no-code creator tooling with marketplace distribution.","consequence":"Connects collection onboarding, primary minting and secondary discovery.","confidence":"high","source_refs":["gamma-platform"]},{"decision":"Specialize in Bitcoin Ordinals.","consequence":"Differentiates the platform while concentrating protocol and market risk.","confidence":"high","source_refs":["gamma-platform"]},{"decision":"Moderate operator surfaces without claiming protocol-level control.","consequence":"Sets an honest enforcement boundary but leaves external asset use beyond Gamma''s control.","confidence":"high","source_refs":["gamma-creator-terms"]}],"counterfactual":{"summary":"Separating launch tooling from the marketplace would reduce vertical integration, but no cited cohort evidence quantifies the retention benefit of keeping them together.","confidence":"low","source_refs":["gamma-platform"]},"watch":[{"signal":"Current-period creator, collector and fee metrics.","implication":"Would distinguish a live product from durable economic growth.","source_refs":["gamma-platform"]},{"signal":"Changes to creator terms or marketplace availability.","implication":"Would reveal a material operating or enforcement shift.","source_refs":["gamma-creator-terms"]}],"unknowns":["Whether current activity is profitable.","How much activity is organic and repeat.","How concentrated revenue is among a small creator cohort.","Whether issuer cumulative metrics are independently auditable."],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-10-29","reviewer":"Chaindump Research"}},"evidence":[{"field":"launch","value":"Bitcoin Ordinals launchpad and marketplace developed during the 2023 Ordinals cycle","as_of":"2023-12-31","basis":"operator","source_ids":["gamma-platform"]},{"field":"supply_or_mint","value":"Not applicable to a platform; operator inventory totals are not fixed supply","as_of":"2026-07-28","basis":"analyst","source_ids":["gamma-platform"]},{"field":"mint_price","value":"Not applicable platform-wide; creator drops set collection-specific economics","as_of":"2026-07-28","basis":"operator","source_ids":["gamma-platform","gamma-creator-terms"]},{"field":"lifecycle_status","value":"thriving — current creator, drop and marketplace surfaces verified; financial performance withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["gamma-platform","gamma-creator-terms"]},{"field":"community_history","value":"Creator tooling, current drops and marketplace inventory remained live","as_of":"2026-07-28","basis":"operator","source_ids":["gamma-platform"]},{"field":"founder_engagement","value":"Nassau Machines Inc. identified as operator; founder and staffing details withheld","as_of":"2026-04-08","basis":"operator","source_ids":["gamma-creator-terms"]},{"field":"benefits","value":"No-code Ordinals launch, primary drops and secondary marketplace","as_of":"2026-07-28","basis":"operator","source_ids":["gamma-platform"]},{"field":"business","value":"Creator-to-marketplace platform; current revenue and profitability withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["gamma-platform","gamma-creator-terms"]},{"field":"analysis","value":"Operational continuity is verified; market leadership and financial success are not established","as_of":"2026-07-28","basis":"analyst","source_ids":["gamma-platform","gamma-creator-terms"]}]},"sources":[{"id":"gamma-ordinals-launch","title":"Create Ordinal Inscriptions on Gamma","url":"https://blog.gamma.io/2023/02/08/create-ordinal-inscriptions-on-gamma","publisher":"Gamma","source_date":"2023-02-08","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false},{"id":"gamma-platform","title":"Gamma Ordinals Marketplace and Creator Launchpad","url":"https://ordinals.gamma.io/","publisher":"Gamma","source_date":"2026-07-28","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false},{"id":"gamma-creator-terms","title":"Gamma Creator Terms","url":"https://ordinals.gamma.io/terms/creators","publisher":"Nassau Machines Inc.","source_date":"2026-04-08","source_date_kind":"updated","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false}]},{"slug":"rarible-marketplace-protocol","name":"Rarible Marketplace & Protocol","chain":"multichain","category":"nft-marketplace-infrastructure","status":"thriving","profile":{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"direct_current","status_as_of":"2026-07-28","last_verified_at":"2026-07-29","next_review_at":"2026-10-29","stale":false},"launched":"Rarible''s first marketplace launch was in November 2019. It evolved into a multichain marketplace-infrastructure stack, and a rebuilt Rarible marketplace launched in September 2025.","supply":"Not applicable: Rarible is a marketplace, indexer, API, SDK and contract stack rather than one collection. Platform mint and user totals are not fixed supply or independently verified holders.","mint_price":"Not applicable platform-wide. Collection creators and sellers choose asset-level economics, and no universal primary-sale price or aggregate creator raise is established.","community_history":"Rarible expanded from a marketplace into APIs, SDKs, smart contracts, branded marketplace infrastructure and RARI Chain support. The operator announced a rebuilt marketplace across 11 chains and a future deprecation path for its older OG interface.","founder_engagement":"The cited documentation establishes active Rarible product and engineering surfaces. It does not establish current founder roles, staffing, financing, treasury or profitability.","benefits":"Users can trade across supported NFT marketplaces and chains; developers can use the indexer, API, SDK and contracts to build marketplace products. The RARI ecosystem also uses rewards, but reward allocation does not prove organic demand.","business":"Rarible combines a consumer marketplace with developer infrastructure and white-label marketplace tooling. Operator claims of thousands of marketplaces and RaribleFUN activity are issuer-reported scale indicators, not audited current users, revenue or profitability.","analysis":"Thriving means the rebuilt marketplace and protocol documentation were current across multiple chains and developer products. It does not establish market leadership, wash-adjusted volume, fee revenue, repeat users, profitability, or that token rewards create sustainable value capture.","team":{"operator":"Rarible","governance_boundary":"The RARI Foundation and token-reward references are ecosystem components; their finances and control rights are not inferred here.","founder_and_staffing_boundary":"Current founder roles and headcount were not established by the cited product documentation.","source_ids":["rarible-introduction","rarible-new-marketplace"]},"chronology":[{"date":"2019-11","event":"Rarible launched its first NFT marketplace.","source_ids":["rarible-year-review"]},{"date":"2023-10","event":"RARI Chain was introduced as an NFT-focused EVM chain with embedded royalty support.","source_ids":["rarible-rari-chain"]},{"date":"2025-09-02","event":"Rarible announced a rebuilt marketplace across 11 chains with points and RARI reward conversion.","source_ids":["rarible-new-marketplace"]},{"date":"2026-07-28","event":"Current documentation listed a multichain API, SDK, indexer, contracts and supported chains.","source_ids":["rarible-introduction","rarible-supported-chains"]}],"market_holder_boundaries":{"market":"No independently verified current marketplace volume, wash-adjusted trades, active-user retention, fee revenue, bid depth, market share or profitability series.","holders":"Not a collection: marketplace users, developer customers, NFT owners, RARI holders and RARI Chain addresses are different populations.","available_evidence":"Current technical and product documentation establishes platform breadth; issuer-reported scale is not treated as audited market performance.","source_ids":["rarible-introduction","rarible-supported-chains","rarible-new-marketplace"]},"products_and_value_capture":{"products":["Consumer NFT marketplace","multichain indexer and API","SDK","smart contracts","community marketplace infrastructure","RARI Chain integration"],"capture":"Marketplace, infrastructure and reward economics exist, but current fees, enterprise revenue, rebates, token emissions, costs and profitability are withheld.","source_ids":["rarible-introduction","rarible-supported-chains","rarible-new-marketplace","rarible-rari-chain"]},"token_model":{"token":"RARI","observed_role":"The September 2025 marketplace announcement says points can convert into RARI distributed by the RARI Foundation.","boundary":"The cited sources do not establish revenue rights, sustainable reward funding, token-holder cash flow or current token economics.","source_ids":["rarible-new-marketplace"]},"chain_dependence":{"current_scope":"The platform and protocol support multiple EVM and non-EVM chains; RARI Chain is an additional NFT-focused execution environment.","implication":"Breadth diversifies single-chain demand but increases indexing, contract, support and liquidity-fragmentation complexity.","source_ids":["rarible-supported-chains","rarible-rari-chain"]},"why":{"finding":"Rarible remains operational by combining consumer trading with reusable marketplace infrastructure across chains. That strategy diversifies distribution beyond one storefront, while the 2025 rebuild and rewards seek renewed consumer activity. The evidence establishes breadth and continuity, not financial success.","source_ids":["rarible-introduction","rarible-supported-chains","rarible-new-marketplace"]},"strategic_choices":[{"choice":"Expand from a consumer marketplace into API, SDK, indexer, contracts and marketplace infrastructure.","consequence":"Rarible can distribute through developer and branded-marketplace customers instead of relying only on its own storefront.","source_ids":["rarible-introduction"]},{"choice":"Support many chains and add RARI Chain rather than specialize on one ecosystem.","consequence":"The addressable inventory broadens while technical support and liquidity fragmentation become more complex.","source_ids":["rarible-supported-chains","rarible-rari-chain"]},{"choice":"Rebuild the consumer marketplace and use points convertible to RARI.","consequence":"The product seeks renewed engagement through a new interface and rewards, but the cited data cannot separate incentive-driven from organic retention.","source_ids":["rarible-new-marketplace"]}],"counterfactual":{"finding":"Remaining only a consumer marketplace would have reduced platform complexity but left Rarible more exposed to storefront competition. The protocol-infrastructure strategy broadens distribution, although no cited segment economics prove that it improves margins or retention.","source_ids":["rarible-introduction","rarible-supported-chains","rarible-new-marketplace"]},"risks":[{"risk":"Token rewards can inflate activity without proving organic retention.","source_ids":["rarible-new-marketplace"]},{"risk":"Multichain support increases indexing, contract and liquidity-fragmentation complexity.","source_ids":["rarible-supported-chains"]},{"risk":"Issuer-reported marketplace counts and RaribleFUN metrics can obscure current economics and repeat usage.","source_ids":["rarible-introduction","rarible-new-marketplace"]}],"unknowns":["Current organic traders, developer customers, repeat retention and market share.","Current wash-adjusted volume, fee revenue, enterprise revenue, costs and profitability.","The share of activity driven by RARI rewards versus unaided demand.","Current founder roles, staffing, financing, treasury and governance control.","Whether the rebuilt marketplace has completed the OG-interface migration without material user loss."],"review":{"last_verified_at":"2026-07-29","next_review_at":"2026-10-29","triggers":["supported-chain change","OG marketplace deprecation","RARI reward-economics change","audited usage or financial disclosure"]},"forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"thriving","summary":"Rarible''s rebuilt multichain marketplace and developer infrastructure remained documented and operational.","confidence":"high","as_of":"2026-07-28","source_refs":["rarible-introduction","rarible-supported-chains","rarible-new-marketplace"]},"why":{"summary":"Combining consumer trading with reusable multichain infrastructure diversifies distribution, although current financial durability is not established.","confidence":"medium","source_refs":["rarible-introduction","rarible-supported-chains"]},"strategic_choices":[{"decision":"Expand into API, SDK, indexer and marketplace infrastructure.","consequence":"Reduced exclusive dependence on the consumer storefront.","confidence":"high","source_refs":["rarible-introduction"]},{"decision":"Support many chains and RARI Chain.","consequence":"Broadened distribution while increasing integration complexity.","confidence":"high","source_refs":["rarible-supported-chains","rarible-rari-chain"]},{"decision":"Rebuild the marketplace and add points convertible to RARI.","consequence":"Creates an acquisition and retention mechanism whose organic durability remains unproven.","confidence":"high","source_refs":["rarible-new-marketplace"]}],"counterfactual":{"summary":"A storefront-only strategy would have been simpler but more exposed to marketplace competition; no cited segment data proves infrastructure diversification is more profitable.","confidence":"low","source_refs":["rarible-introduction","rarible-new-marketplace"]},"watch":[{"signal":"Completion of OG marketplace deprecation and post-migration retention.","implication":"Would test whether the rebuild preserved users without relying on legacy surfaces.","source_refs":["rarible-new-marketplace"]},{"signal":"Audited marketplace, API customer and revenue metrics.","implication":"Would distinguish product breadth from sustainable economics.","source_refs":["rarible-introduction"]}],"unknowns":["Whether current activity is organic and profitable.","How marketplace and infrastructure revenue split.","Whether RARI rewards create durable retention.","How much multichain support costs to maintain."],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-10-29","reviewer":"Chaindump Research"}},"evidence":[{"field":"launch","value":"First marketplace launched in November 2019; rebuilt marketplace launched 2025-09-02","as_of":"2019-11-30","basis":"operator","source_ids":["rarible-year-review","rarible-new-marketplace"]},{"field":"supply_or_mint","value":"Not applicable to a marketplace and protocol stack","as_of":"2026-07-28","basis":"analyst","source_ids":["rarible-introduction"]},{"field":"mint_price","value":"Not applicable platform-wide; creator and seller economics vary","as_of":"2026-07-28","basis":"operator","source_ids":["rarible-introduction"]},{"field":"lifecycle_status","value":"thriving — rebuilt marketplace and multichain infrastructure current; financial performance withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["rarible-introduction","rarible-supported-chains","rarible-new-marketplace"]},{"field":"community_history","value":"Marketplace expanded into multichain developer and branded-marketplace infrastructure","as_of":"2026-07-28","basis":"operator","source_ids":["rarible-introduction","rarible-supported-chains"]},{"field":"founder_engagement","value":"Current product and engineering surfaces verified; founder roles and staffing withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["rarible-introduction"]},{"field":"benefits","value":"Consumer marketplace plus API, SDK, indexer, contracts and multichain support","as_of":"2026-07-28","basis":"operator","source_ids":["rarible-introduction","rarible-supported-chains"]},{"field":"business","value":"Consumer and infrastructure products; current revenue and profitability withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["rarible-introduction","rarible-new-marketplace"]},{"field":"analysis","value":"Operational breadth verified; organic demand, market leadership and financial success are not established","as_of":"2026-07-28","basis":"analyst","source_ids":["rarible-introduction","rarible-supported-chains","rarible-new-marketplace"]}]},"sources":[{"id":"rarible-year-review","title":"Rarible 2020: A Year in Review","url":"https://og.rarible.com/blog/rarible-2020--a-year-in-review-2/","publisher":"Rarible","source_date":"2020-12-24","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"historical_event","stale_after":null,"stale":false},{"id":"rarible-introduction","title":"Rarible Protocol Introduction","url":"https://docs.rarible.org/docs/introduction","publisher":"Rarible","source_date":"2026-01-29","source_date_kind":"updated","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false},{"id":"rarible-supported-chains","title":"Rarible Protocol Supported Chains","url":"https://docs.rarible.org/docs/supported-chains","publisher":"Rarible","source_date":"2026-01-29","source_date_kind":"updated","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false},{"id":"rarible-new-marketplace","title":"New Rarible Marketplace and Rewards","url":"https://og.rarible.com/blog/new-rarible-marketplace-and-rewards/","publisher":"Rarible","source_date":"2025-09-02","source_date_kind":"published","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-10-29","stale":false},{"id":"rarible-rari-chain","title":"What is RARI Chain?","url":"https://rarichain.org/","publisher":"RARI Foundation","source_date":"2026-07-28","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stal