e","stale_after":"2026-08-29","stale":false},{"id":"taproot-portal","title":"Taproot Wizards Collection Portal","url":"https://portal.taprootwizards.com/","publisher":"Taproot Wizards","source_date":"2026-07-28","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-08-29","stale":false}]},{"slug":"solana-monkey-business","name":"Solana Monkey Business (Gen2)","chain":"solana","category":"pfp-community","status":"middling","profile":{"citation_schema":"field-v1","evidence_policy":{"schema":"forensic-freshness-v1","status_basis":"direct_current","status_as_of":"2026-07-28","last_verified_at":"2026-07-29","next_review_at":"2026-08-29","stale":false},"launched":"2021-08-03","supply":5000,"royalties_enforced":"Operator states 5% of each Gen2 secondary sale is sent to the MonkeDAO treasury.","founder_engagement":"Operator site documents a Gen3 expansion and identifies MonkeDAO as steward of Gen2, Gen3 and legacy collectibles.","analysis":"Classified middling because an active expansion and royalty destination are documented, while no current market-cap, floor, liquidity or holder-retention conclusion is supportable from these sources. The lifecycle test is whether Gen3 distribution creates lasting Gen2 utility rather than launch-only attention.","evidence":[{"field":"launch","value":"2021-08-03","as_of":"2021-08-03","basis":"operator","source_ids":["smb-operator"]},{"field":"supply_or_mint","value":"5,000 Gen2 NFTs","as_of":"2021-08-03","basis":"operator","source_ids":["smb-operator"]},{"field":"lifecycle_status","value":"middling — current expansion documented; market-performance claims withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["smb-operator","smb-gen3"]},{"field":"royalties_enforced","value":"5% of each Gen2 secondary sale directed to MonkeDAO treasury","as_of":"2026-07-28","basis":"operator","source_ids":["smb-operator"]},{"field":"founder_engagement","value":"MonkeDAO documents stewardship and Gen3 expansion","as_of":"2026-07-28","basis":"operator","source_ids":["smb-operator","smb-gen3"]},{"field":"analysis","value":"Active expansion verified; floor, liquidity, market-cap and holder-retention conclusions withheld","as_of":"2026-07-28","basis":"analyst","source_ids":["smb-operator","smb-gen3"]}]},"sources":[{"id":"smb-operator","title":"Solana Monkey Business Gen2 and Gen3 Operator Record","url":"https://solanamonkey.business/","publisher":"MonkeDAO","source_date":"2026-07-28","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-08-29","stale":false},{"id":"smb-gen3","title":"Solana Monkey Business Gen3","url":"https://gen3.solanamonkey.business/","publisher":"MonkeDAO","source_date":"2026-07-28","source_date_kind":"observed","last_verified_at":"2026-07-29","evidence_scope":"current_state","stale_after":"2026-08-29","stale":false}]}]')
